import{_ as t,o as e,c as r,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Keynote: Pushing the Limits of Ceph Performance through Software & Hardware Innovation... - Tushar Gohad","description":"","frontmatter":{"title":"Keynote: Pushing the Limits of Ceph Performance through Software & Hardware Innovation... - Tushar Gohad","date":"2019-05-24T00:00:00.000Z","updated":"2019-05-24T00:00:00.000Z","tags":["Ceph","Performance Optimization","Hardware & Software Integration","Storage Solutions","Open Source Community"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/Keynote_-_Pushing_the_Limits_of_Ceph_Performance_through_Software_Hardware_Innova..._-_Tushar_Gohad.md","filePath":"posts/2019/Keynote_-_Pushing_the_Limits_of_Ceph_Performance_through_Software_Hardware_Innova..._-_Tushar_Gohad.md","lastUpdated":1780459816000}'),a={name:"posts/2019/Keynote_-_Pushing_the_Limits_of_Ceph_Performance_through_Software_Hardware_Innova..._-_Tushar_Gohad.md"};function s(_,o,p,h,i,g){return e(),r("div",null,[...o[0]||(o[0]=[n('<h3 id="改进后的中文总结" tabindex="-1">改进后的中文总结 <a class="header-anchor" href="#改进后的中文总结" aria-label="Permalink to &quot;改进后的中文总结&quot;">​</a></h3><p><strong>会议主题</strong>： 推动Ceph性能极限：软件与硬件创新</p><p><strong>会议时间</strong>： 2019年5月24日</p><p><strong>参会人员</strong>： Tushar Gohad（英特尔），Ceph社区成员</p><p><strong>会议内容</strong>：</p><p><strong>一、会议概述</strong></p><p>Tushar Gohad代表英特尔介绍了英特尔在Ceph社区的贡献和发展历程，重点阐述了英特尔在Ceph性能提升方面的努力以及与社区的合作成果。</p><p><strong>二、英特尔在Ceph社区的贡献</strong></p><ol><li><strong>长期贡献历史</strong>： 英特尔自2014年以来一直积极参与Ceph社区，早期主要关注可管理性和企业级功能，近年来则专注于性能提升。</li><li><strong>性能提升</strong>： 英特尔是BlueStore的早期贡献者，并持续优化其通信路径和相关功能。此外，英特尔还参与了Crimson OST项目，并取得了显著进展。</li><li><strong>客户端缓存</strong>： 英特尔正在开发持久双向缓存，并改进了DMA通信，以提升性能。</li><li><strong>容器化支持</strong>： 英特尔是Ceph Container和OpenStack Helm项目的早期参与者，并继续贡献相关技术。</li></ol><p><strong>三、硬件与软件结合</strong></p><p>英特尔通过硬件和软件创新，为Ceph性能提升做出了贡献：</p><ol><li><strong>QLC SSD</strong>： QLC SSD是成本优化的存储解决方案，适用于读密集型工作负载，可扩展至30TB，实现500PB的存储能力。</li><li><strong>高耐用性SSD</strong>： 与标准TLC SSD相比，高耐用性SSD具有更高的耐用性，适用于高性能工作负载。</li><li><strong>第二代Z系列处理器</strong>： 第二代Z系列处理器为Ceph提供了强大的计算能力。</li><li><strong>持久内存</strong>： 持久内存可提升存储和内存之间的性能。</li></ol><p><strong>四、合作成果</strong></p><p>英特尔与合作伙伴和客户合作，共同构建了基于Ceph的新工作负载架构，例如OVH与英特尔合作构建的基于Ceph的存储解决方案。</p><p><strong>五、后续行动计划</strong></p><p>英特尔将继续与Ceph社区合作，推动Ceph性能提升，并探索更多合作机会。</p><p><strong>六、总结</strong></p><p>英特尔在Ceph社区中发挥着重要作用，通过硬件和软件创新，为Ceph性能提升做出了贡献，并与社区共同推动Ceph的发展。</p>',18)])])}const u=t(a,[["render",s]]);export{d as __pageData,u as default};
